use vstd::prelude::*;

verus! {

fn swap_first_and_last(a: &Vec<i32>) -> (result: Vec<i32>)
    requires
        a.len() > 0,
    ensures
        result.len() == a.len(),
        // If length is 1, the vector is unchanged
        a.len() == 1 ==> result@ == a@,
        // If length is > 1, first and last are swapped, others unchanged
        a.len() > 1 ==> (
            result@[0] == a@[a.len() - 1]
            && result@[a.len() - 1] == a@[0]
            && (forall|i: int|
                0 <= i < a.len() && i != 0 && i != a.len() - 1 ==> result@[i] == a@[i]
            )
        ),
{
    let n = a.len();
    debug_assert!(n > 0);

    if n == 1 {
        return a.clone();
    }

    let mut result = a.clone();

    // Help the verifier connect `clone` with sequence equality before mutations.
    assert(result@ == a@);

    result[0] = a[n - 1];
    result[n - 1] = a[0];

    result
}

} // verus!

